import{z as o,x as B,o as t,c as s,q as e,j as l,D as E,d as n,s as i,S as A}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"弹性训练与掉卡","description":"","frontmatter":{"title":"弹性训练与掉卡","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/elastic-training.md","filePath":"llm/elastic-training.md","lastUpdated":1791063341000}'),p={name:"llm/elastic-training.md"};function d(m,a,h,c,D,_){const r=B("Mermaid");return t(),s("div",null,[a[2]||(a[2]=e('<h1 id="弹性训练与掉卡" tabindex="-1">弹性训练与掉卡 <a class="header-anchor" href="#弹性训练与掉卡" aria-label="Permalink to &quot;弹性训练与掉卡&quot;">​</a></h1><div class="epigraph"><p>故障不应当成整场作业的结束：世界缩小后按新的并行计划从上一完好检查点拉起，已训过的 token 尽量接着记账。</p><footer>—— 据 Athlur 等 Varuna、PyTorch Elastic；对照 MegaScale / Llama 3 万卡故障处理整理</footer></div><p><a href="/llm/distributed-ckpt-format">上一课</a>让权重能在新的 TP/PP/EP 度下重切。缺的是控制面：谁发现 rank 没了、如何排空异步 writer、如何选一个仍然合法的并行计划、如何让数据游标在缩小的世界里不重复不遗漏。本课不重讲张量地图字段。缺口是掉卡后的弹性续训。落后者是「还活着但很慢」；本课先处理「已经死了」。故障率课会给万卡的概率背景。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同步集合通信把故障变成全组挂起：All-to-All 与 All-Reduce 没有「缺席默认值」。必须超时检测、中止、从检查点拉起。若每次掉卡都等人工改脚本，MTTR 以小时计，万卡作业的有效时间所剩无几。<span class="marginnote">MTTR（平均修复时间）直译就是「从坏到能用的平均等待」。万卡作业里一次掉卡若靠人肉改脚本重启，MTTR 以小时计；而万卡规模一天可能故障数次——每天等于少训好几个小时。弹性续训把小时压到分钟，靠的正是自动检测加自动选计划，而不是更快的人工。</span>Varuna 一类系统把流水切分随可用机器数重算；torchelastic 提供进程组重建。工程缺口是与 1F1B / MoE EP 组的约束兼容：不是任意 \\(n\\) 都能跑，合法世界大小是离散集合。</p><p>数据侧：弹性后 \\(n_{\\mathrm{dp}}\\) 变了，全局 \\(B\\) 若要保持，就要改 \\(k\\) 或 \\(b_{\\mathrm{micro}}\\)，学习率会计跟着动。游标必须按「已消费 token」而不是按「每个 rank 的文件偏移」恢复，否则 DP 度变化会错位。</p>',6)),(t(),l(A,null,{default:E(()=>[i(r,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIL%5B%22%E6%8E%89%E5%8D%A1%3A%20%E5%AD%98%E6%B4%BB%E6%95%B0%202048%20%E9%99%8D%E4%B8%BA%202040%22%5D%20--%3E%20T%7B%22%E6%9F%A5%E5%90%88%E6%B3%95%E8%AE%A1%E5%88%92%E8%A1%A8%22%7D%0A%20%20T%20--%3E%7C%222040%20%E5%90%88%E6%B3%95%E4%B8%94%20EP%20%E6%95%B4%E9%99%A4%22%7C%20P1%5B%22%E9%80%89%202040%3A%20%E7%BC%A9%208%20%E5%8D%A1%20%E8%AE%A1%E5%88%92%E4%BB%8D%E5%90%88%E6%B3%95%22%5D%0A%20%20T%20--%3E%7C%222040%20%E4%B8%8D%E5%90%88%E6%B3%95%22%7C%20DOWN%5B%22%E6%B2%BF%E7%A6%BB%E6%95%A3%E8%A1%A8%E5%90%91%E4%B8%8B%E6%89%BE%3Cbr%2F%3Edp%20%E7%BC%A9%E5%88%B0%E4%B8%8B%E4%B8%80%E4%B8%AA%E5%8F%AF%E8%A1%8C%E7%82%B9%22%5D%0A%20%20DOWN%20--%3E%20P2%5B%22%E9%80%89%E5%8F%AF%E8%A1%8C%E7%82%B9%20%E4%BE%8B%202016%22%5D%0A%20%20P1%20--%3E%20ADJ%5B%22%E8%B0%83%20micro-batch%20%E6%88%96%20k%3Cbr%2F%3E%E4%BF%9D%E4%BD%8F%E5%85%A8%E5%B1%80%20batch%20%E4%B8%8E%E5%AD%A6%E4%B9%A0%E7%8E%87%E4%BC%9A%E8%AE%A1%22%5D%0A%20%20P2%20--%3E%20ADJ%5B%22%E8%B0%83%20micro-batch%20%E6%88%96%20k%3Cbr%2F%3E%E4%BF%9D%E4%BD%8F%E5%85%A8%E5%B1%80%20batch%20%E4%B8%8E%E5%AD%A6%E4%B9%A0%E7%8E%87%E4%BC%9A%E8%AE%A1%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e('<h3 id="检测要快-但不能误杀" tabindex="-1">检测要快，但不能误杀 <a class="header-anchor" href="#检测要快-但不能误杀" aria-label="Permalink to &quot;检测要快，但不能误杀&quot;">​</a></h3><p>网络抖动与 GC 会造成短暂无响应。超时太短，弹性风暴；太长，空等。应结合 NCCL 健康、心跳、以及「是否卡在同一集合通信」来判定，而不是单 ping。</p><p><span class="marginnote">热备空闲节点可以缩短 MTTR，但要计入利用率。没有热备时，缩小世界继续训往往优于等维修。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>合法计划表：预先枚举若干 \\((n_{\\mathrm{dp}},n_{\\mathrm{tp}},n_{\\mathrm{pp}},n_{\\mathrm{ep}})\\) 组合，掉卡后选不超过当前存活数的最大可行点。从 latest 完好检查点加载，重切分片。排空或取消异步保存队列。重置 CUDA 上下文与通信组。加载器按全局 token 游标恢复，必要时丢掉当前未完成的全局 batch。日志把这次弹性记成一次「非确定性事件」，供重放课声明：弹性后的数值不必与从未掉卡的 run 逐 bit 相同，但 token 会计必须连续。</p><p>盒约束：EP 组大小变化时专家数仍要整除；否则拒绝该计划，继续缩小 DP 而不是强行改专家数。<span class="marginnote">整除约束可以代个数：专家数 8 的 MoE，EP 组大小只能是 8、4、2、1。掉卡后若存活数算出的 EP 组是 6，专家分不匀、路由表对不上权重，这个计划必须整条拒绝——宁可继续缩 DP 换一个整除的数，也不硬改专家布局，改了等于换了个模型。</span></p><h3 id="与退火、评测" tabindex="-1">与退火、评测 <a class="header-anchor" href="#与退火、评测" aria-label="Permalink to &quot;与退火、评测&quot;">​</a></h3><p>弹性发生在退火段时，配比版本号必须从检查点恢复，不能回到 \\(w_{\\mathrm{main}}\\)。训练中评测的进程若与训练共享作业，应一并拉起或显式禁用，避免评测器对着半新权重写结果。</p><p><span class="marginnote">部分框架支持「换一批节点但保持世界大小」。这仍是弹性，只是计划不变、只换机器；检查点仍建议落一次，防止坏 GPU 内存污染。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>集合通信的进程组是静态的。弹性等于结束旧群、在新群上从一致快照重启优化器。丢失的是「上一检查点到故障」之间的梯度，不是整个 run。异步保存若把间隔压到分钟级，丢失可接受。这与数据去污染无关，但与可复现有关：随机数状态若只存在死掉的 rank 上，恢复后噪声不同。</p>',11)),(t(),l(A,null,{default:E(()=>[i(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20FAIL%5B%22%E8%B6%85%E6%97%B6%E5%88%A4%E5%AE%9A%20rank%20%E6%AD%BB%E4%BA%A1%22%5D%20--%3E%20DRAIN%5B%22%E6%8E%92%E7%A9%BA%E5%BC%82%E6%AD%A5%E5%86%99%22%5D%0A%20%20DRAIN%20--%3E%20PLAN%5B%22%E9%80%89%E6%8B%A9%E5%90%88%E6%B3%95%E5%B9%B6%E8%A1%8C%E8%AE%A1%E5%88%92%22%5D%0A%20%20PLAN%20--%3E%20LOAD%5B%22%E6%8C%89%E5%9C%B0%E5%9B%BE%E9%87%8D%E5%88%87%E5%8A%A0%E8%BD%BD%22%5D%0A%20%20LOAD%20--%3E%20CUR%5B%22%E6%8C%89%E5%85%A8%E5%B1%80%20token%20%E6%B8%B8%E6%A0%87%E7%BB%A7%E7%BB%AD%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>弹性不修复慢卡，只修复死卡。缩小世界会改变 \\(B\\) 与通信模式，收敛曲线允许折一下，但应在报告里标注。<span class="marginnote">初学者容易以为弹性续训「无缝恢复，像什么都没发生过」。实际它救的是作业，不是逐 bit 的可复现性：上一检查点到故障之间的梯度丢了，随机数状态可能变，恢复后的曲线与从未掉卡的 run 不必完全一致。这一点要在实验报告里如实标注，而不是当作看不见。</span>下一课处理仍活着的慢节点：它们不会触发超时，却把每一步的墙钟拉到最差 rank。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲分片格式；只补掉卡后选计划、加载、接上 token 会计。</li><li>合法世界大小是离散表；EP 整除约束优先。</li><li>游标按全局 token；弹性事件要记账。</li><li>丢失窗口由异步检查点间隔决定。</li><li>出处：Athlur et al., Varuna, EuroSys 2022；PyTorch Elastic；Jiang et al., MegaScale。</li></ul>',4))])}const T=o(p,[["render",d]]);export{P as __pageData,T as default};
